            "title": outline["title"],
        },
        "parent_revision_id": parent_revision_id,
        "project_id": project_id,
        "schema": REVISION_SCHEMA,
        "sections": [_section_state(item) for item in sections],
        "target_section_id": target_section_id,
        "title": outline["title"],
    }


