def _resolve_output(output: Path) -> Path:
    if not isinstance(output, Path):
        output = Path(output)
    output = output.expanduser()
    if not output.is_absolute():
        output = Path.cwd() / output
    return output


def _symlink_in_parents(path: Path) -> bool:
    current = path.parent
    seen: set[Path] = set()
    while current not in seen:
        seen.add(current)
        if current.exists() and current.is_symlink():
            return True
        if current.parent == current:
            break
        current = current.parent
    return False


def _managed_target(output: Path, workspace: Path) -> bool:
    try:
        relative = output.resolve().relative_to(workspace)
    except ValueError:
        return False
    parts = relative.parts
    if not parts:
        return True
    return parts[0] in _MANAGED_ROOTS


def _output_conflict(message: str, **extra: Any) -> dict[str, Any]:
    return _fail(LIGHT_OUTPUT_CONFLICT, message, **extra)


def _prepare_output_path(output: Path, workspace: Path, *, overwrite: bool) -> tuple[Path, dict[str, Any] | None]:
    given = _resolve_output(output)
    if given.name in {"", ".", ".."}:
        return given, _output_conflict("output must be a Markdown file path", path=str(given))
    if given.is_symlink():
        return given, _output_conflict("output target must be a regular file", path=str(given))
    if given.exists() and given.is_dir():
        return given, _output_conflict("output must be a Markdown file path", path=str(given))
    if _symlink_in_parents(given):
        raise ResearchError(WORKSPACE_INVALID, "output parent path must not traverse a symlink", {"path": str(given)})
    candidate = given.parent.resolve() / given.name

def copy_evidence(items: object) -> list[dict[str, Any]]:
    if type(items) is not list:
        raise ResearchError("LIGHT_QA_INVALID", "evidence must be a list")
    rows = [_copy_evidence_item(item) for item in items]
    seen: set[str] = set()
    for row in rows:
        if row["chunk_id"] in seen:
            raise ResearchError("LIGHT_QA_INVALID", "chunk_id is duplicated")
        seen.add(row["chunk_id"])
    return rows


def inspect_retrieval(retrieval: object) -> dict[str, Any]:
    doc = _require_dict(retrieval, "retrieval")
    status = doc.get("status")
    evidence = copy_evidence(doc.get("evidence") or [])
    index_id = doc.get("index_id")
    query = doc.get("query")
    message = doc.get("message") if type(doc.get("message")) is str else ""
    if doc.get("ok") is not True or status != OK:
        if status == INDEX_STALE:
            return _fail(INDEX_STALE, message or "index is stale", evidence=[], index_id=index_id, query=query)
        if status == NO_RESULTS or (doc.get("ok") is True and not evidence):
            return _fail(NO_RESULTS, message or "no matching evidence", evidence=[], index_id=index_id, query=query)
        if status in {NO_RESULTS, INDEX_STALE, INSUFFICIENT_EVIDENCE}:
            return _fail(str(status), message or str(status), evidence=evidence, index_id=index_id, query=query)
        return _fail(
            str(status or "QUERY_INVALID"),
            message or "retrieval is not usable",
            evidence=evidence,
            index_id=index_id,
            query=query,
        )
    return {
        "ok": True,
        "status": OK,
        "query": query,
        "index_id": index_id,
        "evidence": evidence,
        "message": message,
    }


def _context(
    *,
    kind: str,
    query: str,
    requirements: str,
    paper_ids: list[str],
    inspected: dict[str, Any],
    prompt: str,
) -> dict[str, Any]:
    if not inspected.get("ok"):
        payload = copy.deepcopy(inspected)
        payload["schema"] = CONTEXT_SCHEMA
        payload["kind"] = kind
        payload["query"] = query
        payload["requirements"] = requirements
        payload["paper_ids"] = list(paper_ids)
        payload["prompt"] = ""
        payload.setdefault("evidence", [])
        return payload
    evidence = inspected["evidence"]
    if not evidence:
        return {
            "ok": False,
            "status": INSUFFICIENT_EVIDENCE,
            "schema": CONTEXT_SCHEMA,
            "kind": kind,
            "query": query,
            "requirements": requirements,
            "paper_ids": list(paper_ids),
            "index_id": inspected.get("index_id"),
            "evidence": [],
            "prompt": "",
            "markdown": "",
            "citations": [],
            "message": "no evidence is available for the current model",
        }
    return {
        "ok": True,
        "status": OK,
        "schema": CONTEXT_SCHEMA,
        "kind": kind,
        "query": query,
        "requirements": requirements,
        "paper_ids": list(paper_ids),
        "index_id": inspected.get("index_id"),
        "evidence": copy.deepcopy(evidence),
        "prompt": prompt,
        "message": "exported local context for the current conversation model",
    }


def export_qa_context(question: str, retrieval: dict) -> dict:
    if type(question) is not str:
        raise ResearchError("LIGHT_QA_INVALID", "question must be a string")
    inspected = inspect_retrieval(retrieval)
    paper_ids: list[str] = []
    if inspected.get("ok"):
        paper_ids = list(dict.fromkeys(item["paper_id"] for item in inspected["evidence"]))
    return _context(
        kind="qa",
        query=question,
        requirements="",
        paper_ids=paper_ids,
        inspected=inspected,
