        _raise(LIGHT_WRITING_PROJECT_INVALID, f"{name} must be a path")
        raise AssertionError("unreachable")
    path = path.expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    return Path(os.path.normpath(path))


def _require_work_output(output: object) -> Path:
    given = _absolute_path(output, "output")
    if given.suffix != ".md" or given.name in {"", ".", ".."}:
        _raise(LIGHT_WRITING_PROJECT_INVALID, "output must be a .md file path", {"path": str(given)})
    if not _has_work_component(given):
        _raise(WORKSPACE_INVALID, "output must be under .work/**", {"path": str(given)})
    if _symlink_in_chain(given):
        _raise(WORKSPACE_INVALID, "output path must not traverse a symlink", {"path": str(given)})
    parent = given.parent
    if parent.exists():
        if parent.is_symlink() or not parent.is_dir() or _symlink_in_chain(parent):
            _raise(WORKSPACE_INVALID, "output path must not traverse a symlink", {"path": str(given)})
        resolved = parent.resolve() / given.name
        if not _has_work_component(resolved):
            _raise(WORKSPACE_INVALID, "output must be under .work/**", {"path": str(resolved)})
        return resolved
    return given


