HEX64 = re.compile(r"^[0-9a-f]{64}$")
SECTION_ID = re.compile(r"^s[1-9][0-9]?$")
_CONTROL = re.compile(r"[\x00-\x1f\x7f]")

OUTLINE_MESSAGE = "exported writing outline context for the current conversation model"
OUTLINE_PROMPT = (
