HEAD_SCHEMA = "video-paper-wiki.light-writing-head.v1"
RESULT_SCHEMA = "video-paper-wiki.light-writing-result.v1"
HISTORY_SCHEMA = "video-paper-wiki.light-writing-history.v1"
