    sha256_canonical,
)

LIGHT_WRITING_PROJECT_INVALID = "LIGHT_WRITING_PROJECT_INVALID"
LIGHT_WRITING_PROJECT_CONFLICT = "LIGHT_WRITING_PROJECT_CONFLICT"

WRITING_DIRNAME = ".light-writing"
