    "ok",
    "status",
    "message",
    "schema",
    "project_id",
    "parent_revision_id",
    "section_id",
    "context",
    "context_sha256",
    "outline",
    "previous_section",
    "instructions",
    "prompt",
    "wrapper_sha256",
)
