LIVE_STATUSES = frozenset(
    {
        INDEX_STALE,
        SOURCE_INVALID,
        LIGHT_SELECTION_INVALID,
        LIGHT_CONTEXT_INVALID,
        LIGHT_WORKSPACE_MISMATCH,
