HEX64 = re.compile(r"^[0-9a-f]{64}$")
SECTION_ID = re.compile(r"^s[1-9][0-9]?$")
_CONTROL = re.compile(r"[\x00-\x1f\x7f]")
_MARKDOWN_WS = frozenset("\n\r\t")
_MANAGED_OUTPUT_ROOTS = frozenset(
    {
        WRITING_DIRNAME,
        ".light-index",
        "papers",
        ".light-knowledge",
        ".light-library",
        ".light-workflow",
        ".light-transactions",
